using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Web.Script.Serialization;
namespace HDRemix.LunaCosmetics {
    internal static class SemanticTests {
        static readonly List<string> Passed=new List<string>();
        static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
        static void Test(string name,Action action){action();Passed.Add(name);Console.WriteLine("PASS "+name);}
        static void Refuses(Action action,string part){try{action();}catch(Exception e){Check(e.Message.IndexOf(part,StringComparison.OrdinalIgnoreCase)>=0,"Unexpected failure: "+e);return;}throw new Exception("Expected refusal: "+part);}
        static void Put(byte[] b,int at,uint value){Buffer.BlockCopy(BitConverter.GetBytes(value),0,b,at,4);}
        static string ArmorPath(string r){return Path.Combine(r,ExportCore.RelativeTarget.Replace('/',Path.DirectorySeparatorChar));}
        static string EntityPath(string r){return Path.Combine(r,ExportCore.EntityTarget.Replace('/',Path.DirectorySeparatorChar));}
        static void Write(string r,byte[] a,byte[] e){File.WriteAllBytes(ArmorPath(r),a);File.WriteAllBytes(EntityPath(r),e);}
        static void Preserved(byte[] before,byte[] after,HashSet<int> allowed){
            Check(after.Length>=before.Length&&after.Length<=before.Length+15,"Unexpected length change");
            for(int i=0;i<before.Length;i++)Check(before[i]==after[i]||allowed.Contains(i),"Unrelated byte changed at "+i);
            Check(SemanticEditor.Murmur(before)==SemanticEditor.Murmur(after),"Resource identifier changed");
        }
        static HashSet<int> AllowedArmor(byte[] before){var s=new HashSet<int>();var edits=new JavaScriptSerializer().Deserialize<EditSchema>(System.Text.Encoding.UTF8.GetString(Program.Resource("Schema"))).changes.Select(e=>e.definition).ToHashSetCompat();var blocks=SemanticEditor.ArmorBlocks(before);foreach(var b in blocks)if(edits.Contains(SemanticEditor.U32(before,b.payload)))for(int i=0;i<4;i++)s.Add(b.payload+4+i);for(int i=0;i<4;i++)s.Add(blocks.Last().header+12+i);return s;}
        static HashSet<int> AllowedArcade(byte[] before){var blocks=SemanticEditor.EntityBlocks(before);int z=SemanticEditor.ArcadeZone(before,blocks);var s=new HashSet<int>{z+45};foreach(int offset in new[]{48,80})for(int i=0;i<4;i++)s.Add(z+offset+i);for(int i=0;i<4;i++)s.Add(blocks.Last().header+12+i);return s;}
        static void SameFiles(string root,string a,string e){Check(ExportCore.FileHash(ArmorPath(root))==a&&ExportCore.FileHash(EntityPath(root))==e,"Files changed unexpectedly");}
        static int Main(string[] args){try{Run(args[0]);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
        static void Run(string dir){
            var c=Catalog.Parse(Program.Resource("Profiles"));var core=new ExportCore(c);Action<int,string> progress=delegate{};
            byte[] stock=File.ReadAllBytes(Path.Combine(dir,"stock-armor.bin")),entity=File.ReadAllBytes(Path.Combine(dir,"stock-entity.bin")),workbench=File.ReadAllBytes(Path.Combine(dir,"workbench.bin"));
            string stage=Path.Combine(dir,"dummy_game"),direct=Path.Combine(dir,"game-copy");
            byte[] plain=GameBox.Decrypt(stock),ep=GameBox.Decrypt(entity);byte[] all=null,arcade=null,novelArmor=null,novelEntity=null;
            Test("public format crypto round trip and authentication failure",delegate{Check(GameBox.Decrypt(GameBox.Encrypt(plain)).SequenceEqual(plain),"Crypto roundtrip");var bad=(byte[])stock.Clone();bad[100]^=1;Refuses(()=>GameBox.Decrypt(bad),"authentication");});
            Test("reference resource identifiers",delegate{Check(SemanticEditor.Murmur(plain)==0x57a949680bbda9e1UL,"Armor Murmur differs from independent reference");Check(SemanticEditor.Murmur(ep)==0x8e49771b181ffaa1UL,"Entity Murmur differs from independent reference");});
            Test("all 111 targets exactly reproduce previously tested cosmetic plaintext",delegate{all=SemanticEditor.Armor(stock,63,c);var output=GameBox.Decrypt(all);Check(output.SequenceEqual(File.ReadAllBytes(Path.Combine(dir,"expected-all.plain"))),"All-on plaintext differs from tested implementation");Preserved(plain,output,AllowedArmor(plain));File.WriteAllBytes(Path.Combine(dir,"new-all.bin"),all);});
            Test("no-op preserves exact ciphertext and does not append footer",delegate{Check(SemanticEditor.Armor(all,63,c).SequenceEqual(all),"No-op armor changed");Check(SemanticEditor.Armor(stock,0,c).SequenceEqual(stock),"Off no-op changed");});
            Test("all cosmetic category masks preserve unrelated data and restore managed fields",delegate{for(int mask=0;mask<64;mask++){var output=GameBox.Decrypt(SemanticEditor.Armor(all,mask,c));Preserved(GameBox.Decrypt(all),output,AllowedArmor(GameBox.Decrypt(all)));var blocks=SemanticEditor.ArmorBlocks(output).ToDictionary(b=>SemanticEditor.U32(output,b.payload));var changes=new JavaScriptSerializer().Deserialize<EditSchema>(System.Text.Encoding.UTF8.GetString(Program.Resource("Schema"))).changes.ToDictionary(e=>e.definition);foreach(var g in c.groups)foreach(var i in g.items)Check(SemanticEditor.U32(output,blocks[(uint)i.definition].payload+4)==((g.bit&mask)!=0?changes[(uint)i.definition].after_tag:changes[(uint)i.definition].before_tag),"Mask mismatch "+mask);}});
            Test("unfamiliar Workbench edits survive semantic cosmetic patching",delegate{var before=GameBox.Decrypt(workbench);var after=GameBox.Decrypt(SemanticEditor.Armor(workbench,63,c));Preserved(before,after,AllowedArmor(before));});
            Test("fresh encrypted reordered catalog with novel unrelated edits is accepted",delegate{var blocks=SemanticEditor.ArmorBlocks(plain);var pieces=blocks.Select(b=>plain.Skip(b.header).Take(b.size+24).ToArray()).ToList();var swap=pieces[0];pieces[0]=pieces[1];pieces[1]=swap;using(var m=new MemoryStream()){m.Write(plain,0,4);foreach(var p in pieces)m.Write(p,0,p.Length);var novel=m.ToArray();novel[28+16]^=0x12;novelArmor=GameBox.Encrypt(novel);var output=SemanticEditor.Armor(novelArmor,63,c);Preserved(novel,GameBox.Decrypt(output),AllowedArmor(novel));File.WriteAllBytes(Path.Combine(dir,"novel-armor-before.bin"),novelArmor);File.WriteAllBytes(Path.Combine(dir,"novel-armor-after.bin"),output);}});
            Test("missing selected definition is skipped without fabricating a progression record",delegate{var b=(byte[])plain.Clone();var block=SemanticEditor.ArmorBlocks(b).First(x=>SemanticEditor.U32(b,x.payload)==c.groups[0].items[0].definition);Put(b,block.payload,0xfefdfcfa);var output=GameBox.Decrypt(SemanticEditor.Armor(GameBox.Encrypt(b),1,c));Check(SemanticEditor.ArmorBlocks(output).Count==422,"Invented record");});
            Test("specific overlapping availability edit refuses only selected category",delegate{var b=(byte[])plain.Clone();var block=SemanticEditor.ArmorBlocks(b).First(x=>SemanticEditor.U32(b,x.payload)==c.groups[0].items[0].definition);Put(b,block.payload+4,0xdead1234);var input=GameBox.Encrypt(b);Refuses(()=>SemanticEditor.Armor(input,1,c),"availability field");Check(GameBox.Decrypt(SemanticEditor.Armor(input,2,c))[block.payload+4]==b[block.payload+4],"Unselected overlap lost");});
            Test("malformed catalog bounds and duplicate IDs are refused",delegate{var b=(byte[])plain.Clone();Put(b,16,0xffffffff);Refuses(()=>SemanticEditor.Armor(GameBox.Encrypt(b),1,c),"bounds");b=(byte[])plain.Clone();var blocks=SemanticEditor.ArmorBlocks(b);Put(b,blocks[1].payload,SemanticEditor.U32(b,blocks[0].payload));Refuses(()=>SemanticEditor.Armor(GameBox.Encrypt(b),1,c),"duplicate");});
            Test("arcade changes exactly three known fields and preserves resource hash",delegate{arcade=SemanticEditor.Arcade(entity,true);Preserved(ep,GameBox.Decrypt(arcade),AllowedArcade(ep));int z=SemanticEditor.ArcadeZone(ep,SemanticEditor.EntityBlocks(ep));var b=GameBox.Decrypt(arcade);Check(b[z+45]==1&&SemanticEditor.U32(b,z+48)==0x3f800000&&SemanticEditor.U32(b,z+80)==0x63b171e5,"Arcade fields");File.WriteAllBytes(Path.Combine(dir,"new-arcade.bin"),arcade);});
            Test("arcade enable idempotent and disable preserves every unrelated field",delegate{Check(SemanticEditor.Arcade(arcade,true).SequenceEqual(arcade),"Arcade no-op");Preserved(GameBox.Decrypt(arcade),GameBox.Decrypt(SemanticEditor.Arcade(arcade,false)),AllowedArcade(GameBox.Decrypt(arcade)));});
            Test("novel ship modification accepted without a hash whitelist",delegate{var b=(byte[])ep.Clone();var blocks=SemanticEditor.EntityBlocks(b);b[blocks.First(x=>x.type!=0xfcca29db).payload]^=0x55;novelEntity=GameBox.Encrypt(b);var after=SemanticEditor.Arcade(novelEntity,true);Preserved(b,GameBox.Decrypt(after),AllowedArcade(b));File.WriteAllBytes(Path.Combine(dir,"novel-entity-before.bin"),novelEntity);File.WriteAllBytes(Path.Combine(dir,"novel-entity-after.bin"),after);});
            Test("unknown arcade callback and out-of-bounds index refused",delegate{var b=(byte[])ep.Clone();var blocks=SemanticEditor.EntityBlocks(b);int z=SemanticEditor.ArcadeZone(b,blocks);Put(b,z+80,0x12345678);Refuses(()=>SemanticEditor.Arcade(GameBox.Encrypt(b),true),"callback");b=(byte[])ep.Clone();var table=blocks.Single(x=>x.type==0xfcca29db);for(int i=0;i<1124;i++)if(SemanticEditor.U64(b,table.payload+i*16)==0x927f0eb8d641607dUL){Put(b,table.payload+i*16+8,562);break;}Refuses(()=>SemanticEditor.Arcade(GameBox.Encrypt(b),true),"index");});
            foreach(string fixture in new[]{"private-prior-entity.bin","private-trial-entity.bin"})if(File.Exists(Path.Combine(dir,fixture)))Test("previously rejected user file: "+fixture,delegate{var b=File.ReadAllBytes(Path.Combine(dir,fixture));var before=GameBox.Decrypt(b);Preserved(before,GameBox.Decrypt(SemanticEditor.Arcade(b,true)),AllowedArcade(before));});
            Test("Luna combined transaction handles novel catalog and ship data",delegate{Write(stage,novelArmor,novelEntity);core.Export(stage,65,progress);Check(core.DetectMask(stage)==65,"Detection failed");Preserved(GameBox.Decrypt(novelArmor),GameBox.Decrypt(File.ReadAllBytes(ArmorPath(stage))),AllowedArmor(GameBox.Decrypt(novelArmor)));});
            Test("explicit leave ship unchanged bypasses even unparseable entity file",delegate{Write(stage,stock,new byte[]{1,2,3});core.Export(stage,129,progress);Check(File.ReadAllBytes(EntityPath(stage)).SequenceEqual(new byte[]{1,2,3}),"Ship touched");});
            Test("explicit Luna save captures both already-enabled resources without changing plaintext",delegate{Write(stage,all,arcade);string a=ExportCore.Hash(all),e=ExportCore.Hash(arcade);core.Export(stage,127,progress,true);Check(ExportCore.FileHash(ArmorPath(stage))!=a&&ExportCore.FileHash(EntityPath(stage))!=e,"Luna would capture zero files");Check(GameBox.Decrypt(File.ReadAllBytes(ArmorPath(stage))).SequenceEqual(GameBox.Decrypt(all)),"No-op armor plaintext changed");Check(GameBox.Decrypt(File.ReadAllBytes(EntityPath(stage))).SequenceEqual(GameBox.Decrypt(arcade)),"No-op arcade plaintext changed");a=ExportCore.FileHash(ArmorPath(stage));e=ExportCore.FileHash(EntityPath(stage));core.Export(stage,127,progress,true);Check(ExportCore.FileHash(ArmorPath(stage))!=a&&ExportCore.FileHash(EntityPath(stage))!=e,"Repeat capture missing");Check(GameBox.Decrypt(File.ReadAllBytes(EntityPath(stage))).SequenceEqual(GameBox.Decrypt(arcade)),"Repeat capture grew footer or changed data");});
            Test("explicit Luna capture still honors leave ship unchanged",delegate{Write(stage,all,new byte[]{3,2,1});core.Export(stage,191,progress,true);Check(ExportCore.FileHash(ArmorPath(stage))!=ExportCore.Hash(all),"No cosmetic output captured");Check(File.ReadAllBytes(EntityPath(stage)).SequenceEqual(new byte[]{3,2,1}),"Preserve mode touched ship");});
            Test("two-file validation failure makes no staged writes",delegate{Write(stage,stock,new byte[]{1,2,3});string a=ExportCore.FileHash(ArmorPath(stage)),e=ExportCore.FileHash(EntityPath(stage));Refuses(()=>core.Export(stage,65,progress),"size");SameFiles(stage,a,e);});
            Test("Luna second-commit failure rolls back both exact inputs",delegate{Write(stage,novelArmor,novelEntity);string a=ExportCore.FileHash(ArmorPath(stage)),e=ExportCore.FileHash(EntityPath(stage));core.AfterCommitForTest=n=>{if(n==2)throw new IOException("test second commit failure");};try{Refuses(()=>core.Export(stage,127,progress),"test second commit");}finally{core.AfterCommitForTest=null;}SameFiles(stage,a,e);});
            Test("Luna changed input between commits is preserved during rollback refusal",delegate{Write(stage,stock,entity);byte[] outside={9,8,7};core.AfterCommitForTest=n=>{if(n==1){File.WriteAllBytes(ArmorPath(stage),outside);throw new IOException("outside writer");}};try{Refuses(()=>core.Export(stage,127,progress),"rollback");}finally{core.AfterCommitForTest=null;}Check(File.ReadAllBytes(ArmorPath(stage)).SequenceEqual(outside),"Overwrote concurrent writer");});
            Test("standalone public mode, exact backup, category update and restore",delegate{Write(direct,novelArmor,novelEntity);var d=new StandaloneCore(c,core,Path.Combine(dir,"backup-store"),()=>false,Path.Combine(dir,"empty-legacy"));string a=ExportCore.FileHash(ArmorPath(direct)),e=ExportCore.FileHash(EntityPath(direct));d.Install(direct,127,progress);Check(d.DetectMask(direct)==127&&d.HasRestore(direct),"Direct install/detection");d.Install(direct,130,progress);Check(d.DetectMask(direct)==66,"Category update should leave enabled ship unchanged");d.Restore(direct,progress);SameFiles(direct,a,e);});
            Test("standalone two-file commit failure restores exact files",delegate{Write(direct,stock,entity);var d=new StandaloneCore(c,core,Path.Combine(dir,"rollback-store"),()=>false,Path.Combine(dir,"empty-legacy"));string a=ExportCore.FileHash(ArmorPath(direct)),e=ExportCore.FileHash(EntityPath(direct));d.AfterCommitForTest=n=>{if(n==2)throw new IOException("test standalone failure");};Refuses(()=>d.Install(direct,127,progress),"test standalone");SameFiles(direct,a,e);});
            Test("verified old helper backup can still be adopted without input whitelisting",delegate{Write(direct,File.ReadAllBytes(Path.Combine(dir,"legacy-installed.bin")),entity);string legacy=Path.Combine(dir,"old");string folder=Path.Combine(legacy,"Backups","Build-26251122",ExportCore.Hash(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(direct).ToLowerInvariant())).Substring(0,32));Directory.CreateDirectory(folder);File.WriteAllBytes(Path.Combine(folder,ExportCore.Hash(stock)+".original"),stock);File.WriteAllText(Path.Combine(folder,"backup.json"),new JavaScriptSerializer().Serialize(new LegacyBackupRecord{Version=1,GameRoot=Path.GetFullPath(direct),OriginalHash=ExportCore.Hash(stock)}));var d=new StandaloneCore(c,core,Path.Combine(dir,"adopt-store"),()=>false,legacy);Check(d.HasRestore(direct),"Legacy backup not found");d.Restore(direct,progress);Check(File.ReadAllBytes(ArmorPath(direct)).SequenceEqual(stock),"Legacy exact restore failed");});
            Test("standalone refuses running game and later external modifications",delegate{var d=new StandaloneCore(c,core,Path.Combine(dir,"guard-store"),()=>true,Path.Combine(dir,"empty-legacy"));Refuses(()=>d.Install(direct,127,progress),"Close");d=new StandaloneCore(c,core,Path.Combine(dir,"guard-store"),()=>false,Path.Combine(dir,"empty-legacy"));Write(direct,stock,entity);d.Install(direct,129,progress);File.WriteAllBytes(ArmorPath(direct),novelArmor);Refuses(()=>d.Restore(direct,progress),"changed");Check(File.ReadAllBytes(ArmorPath(direct)).SequenceEqual(novelArmor),"External data overwritten");});
            Test("missing original backup refuses restore",delegate{Write(direct,stock,entity);string store=Path.Combine(dir,"missing-store");var d=new StandaloneCore(c,core,store,()=>false,Path.Combine(dir,"empty-legacy"));d.Install(direct,129,progress);foreach(string p in Directory.GetFiles(store,"*.original",SearchOption.AllDirectories))File.Delete(p);Refuses(()=>d.Restore(direct,progress),"backup");});
            Test("build guard, mode guard and invalid mask remain enforced",delegate{Refuses(()=>core.Export(stage,192,progress),"invalid");Refuses(()=>core.Export(direct,129,progress),"dummy_game");Check(!Program.Options.Parse(new string[0]).loader,"Default mode");Refuses(()=>Program.Options.Parse(new[]{"--loader-mode"}),"Configure");var pin=c.build_hashes.First();string p=Path.Combine(stage,pin.Key.Replace('/',Path.DirectorySeparatorChar));var data=File.ReadAllBytes(p);try{File.WriteAllBytes(p,new byte[]{0});Refuses(()=>core.Export(stage,129,progress),"build");}finally{File.WriteAllBytes(p,data);}});
            Test("new hotfix native build pins reject previous executables in both modes",delegate{
                foreach(var pin in c.build_hashes){string a=Path.Combine(stage,pin.Key.Replace('/',Path.DirectorySeparatorChar)),d=Path.Combine(direct,pin.Key.Replace('/',Path.DirectorySeparatorChar));byte[] current=File.ReadAllBytes(a),old=File.ReadAllBytes(Path.Combine(dir,"previous-build",pin.Key.Replace('/',Path.DirectorySeparatorChar)));try{File.WriteAllBytes(a,old);File.WriteAllBytes(d,old);Write(stage,stock,entity);Write(direct,stock,entity);string ah=ExportCore.FileHash(ArmorPath(stage)),eh=ExportCore.FileHash(EntityPath(stage));Refuses(()=>core.Export(stage,127,progress),"build");SameFiles(stage,ah,eh);var standalone=new StandaloneCore(c,core,Path.Combine(dir,"old-build-guard"),()=>false,Path.Combine(dir,"empty-legacy"));Refuses(()=>standalone.Install(direct,127,progress),"build");SameFiles(direct,ah,eh);}finally{File.WriteAllBytes(a,current);File.WriteAllBytes(d,current);}}
            });
            Test("standalone backups are isolated from pre-hotfix install records",delegate{
                Write(direct,stock,entity);string store=Path.Combine(dir,"build-isolation-store"),id=ExportCore.Hash(System.Text.Encoding.UTF8.GetBytes(Path.GetFullPath(direct).ToLowerInvariant())).Substring(0,32),oldFolder=Path.Combine(store,"Backups","Build-26088801",id);Directory.CreateDirectory(oldFolder);string oldRecord=Path.Combine(oldFolder,"install-state.json");File.WriteAllText(oldRecord,"previous-build record must remain untouched");var d=new StandaloneCore(c,core,store,()=>false,Path.Combine(dir,"empty-legacy"));Check(d.BackupFolder(direct).Contains("Build-26251122"),"Wrong backup build");d.Install(direct,127,progress);d.Restore(direct,progress);Check(File.ReadAllText(oldRecord)=="previous-build record must remain untouched","Old backup modified");SameFiles(direct,ExportCore.Hash(stock),ExportCore.Hash(entity));
            });
            Passed.AddRange(SwapTests.Run(dir,c));
            Passed.AddRange(PaddingTests.Run(dir,c));
            File.WriteAllText(Path.Combine(dir,"Test-results.json"),new JavaScriptSerializer().Serialize(new{passed=Passed.Count,scenarios=Passed,category_masks=64,live_game_writes=0,in_game_verified=false}));Console.WriteLine("TOTAL "+Passed.Count);
        }
        static HashSet<T> ToHashSetCompat<T>(this IEnumerable<T> items){return new HashSet<T>(items);}
    }
}
